import copy
import fnmatch
import hashlib
import json
import math
from collections import deque
from collections.abc import Mapping

_ALLOWED_FIELDS = frozenset(
    {
        "id",
        "effect",
        "priority",
        "subject",
        "action",
        "resource",
        "subject_exclude",
        "action_exclude",
        "resource_exclude",
        "tags",
        "tag_patterns",
        "tag_exclude_patterns",
        "tag_presence",
    }
)
_STRING_FIELDS = ("subject", "action", "resource")
_EXCLUSION_FIELDS = ("subject_exclude", "action_exclude", "resource_exclude")
_REQUEST_FIELDS = frozenset({"subject", "action", "resource", "tags"})
_CASE_FIELDS = frozenset(
    {"subject", "action", "resource", "tags", "expected"}
)
_EXPECTATION_FIELDS = frozenset({"effect", "rule"})
_REQUIRED_CASE_FIELDS = ("subject", "action", "resource", "expected")
_DOCUMENT_FIELDS = frozenset({"version", "rules", "fingerprint"})
_SUPPORTED_DOCUMENT_VERSION = 1
_FINGERPRINT_ALPHABET = frozenset("0123456789abcdef")


class PolicyConfigError(Exception):
    """A JSON policy document could not be loaded.

    The machine-readable ``code`` attribute distinguishes failure classes:
    ``invalid_json``, ``duplicate_key``, ``root_not_array_or_object``,
    ``rule_not_object`` or, for a versioned document object,
    ``unknown_document_field``, ``missing_version``, ``invalid_version``,
    ``unsupported_version``, ``missing_rules``, ``rules_not_array``,
    ``invalid_fingerprint`` or ``fingerprint_mismatch``. Semantic problems
    inside an otherwise well-formed rule object keep raising plain
    ``ValueError`` (see ``PolicyGate``).
    """

    def __init__(self, code, message):
        self.code = code
        super().__init__("[%s] %s" % (code, message))


class PolicyBatchError(Exception):
    """A batch handed to :meth:`PolicyGate.decide_many` failed validation.

    The machine-readable ``code`` attribute is one of ``invalid_batch``,
    ``item_not_mapping``, ``unknown_field``, ``missing_field`` or
    ``invalid_field_type``. ``index`` is the offending element index, or
    ``None`` when the outer batch value itself is not a list or tuple.
    ``field`` names the offending request field for the field-level codes
    and is ``None`` otherwise.
    """

    def __init__(self, code, index, field=None, message=None):
        self.code = code
        self.index = index
        self.field = field
        if message is None:
            message = self._default_message(code, index, field)
        super().__init__("[%s] %s" % (code, message))

    @staticmethod
    def _default_message(code, index, field):
        if code == "invalid_batch":
            return "batch must be a list or tuple of request mappings"
        if code == "item_not_mapping":
            return "request at index %s must be a mapping" % index
        if code == "unknown_field":
            return "request at index %d contains unknown field %r" % (index, field)
        if code == "missing_field":
            return "request at index %d is missing required field %r" % (index, field)
        if code == "invalid_field_type":
            return "request at index %d field %r has an invalid type" % (index, field)
        return "batch validation failed"


class PolicyVerificationError(Exception):
    """A batch handed to :meth:`PolicyGate.verify` failed validation.

    The machine-readable ``code`` attribute is one of ``invalid_cases``,
    ``item_not_mapping``, ``unknown_field``, ``missing_field``,
    ``invalid_field_type`` or ``invalid_expectation``. ``index`` is the
    offending element index, or ``None`` when the outer batch value itself
    is not a list or tuple. ``field`` names the offending field for the
    field-level codes (nested expectation fields are written
    ``expected.effect`` / ``expected.rule``) and is ``None`` otherwise.
    """

    def __init__(self, code, index, field=None, message=None):
        self.code = code
        self.index = index
        self.field = field
        if message is None:
            message = self._default_message(code, index, field)
        super().__init__("[%s] %s" % (code, message))

    @staticmethod
    def _default_message(code, index, field):
        if code == "invalid_cases":
            return "cases must be a list or tuple of case mappings"
        if code == "item_not_mapping":
            return "case at index %s must be a mapping" % index
        if code == "unknown_field":
            return "case at index %d contains unknown field %r" % (index, field)
        if code == "missing_field":
            return "case at index %d is missing required field %r" % (index, field)
        if code == "invalid_field_type":
            return "case at index %d field %r has an invalid type" % (index, field)
        if code == "invalid_expectation":
            return "case at index %d field %r has an invalid value" % (index, field)
        return "case validation failed"


class _DuplicateKeyError(ValueError):
    """Raised internally by the JSON object hook when a key repeats."""


def _reject_duplicate_keys(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise _DuplicateKeyError(key)
        obj[key] = value
    return obj


def _reject_constant(value):
    # json.loads accepts NaN/Infinity by default; strict JSON does not.
    raise ValueError("invalid JSON constant %r" % value)


def _json_snapshot_error(kind):
    return ValueError("[non_json_value] rule snapshot contains %s" % kind)


def _deepcopy_rule_mapping(value, index, field):
    """Independently deep-copy one caller-provided rule mapping.

    A directly constructed gate must own its rule data: without this
    copy the normalized rule would alias the caller's mapping, so later
    mutations of the rule dict or any nested container would silently
    change decisions. Deep copying preserves each value's concrete
    type and equality for every acceptable configuration; a value that
    cannot be copied on its own aborts construction with a ValueError
    tagged ``non_copyable_value`` (callers distinguish this from the
    snapshot-time ``non_json_value`` failures raised for values that
    copy perfectly but have no strict-JSON representation).
    """
    try:
        return copy.deepcopy(value)
    except Exception:
        raise ValueError(
            "[non_copyable_value] rule %d: field %r contains a value that "
            "cannot be independently copied" % (index, field)
        ) from None


class _FixedObject:
    """A JSON object whose keys must appear in a fixed order."""

    __slots__ = ("pairs",)

    def __init__(self, pairs):
        self.pairs = pairs


def _canonical_json(value):
    """Serialize normalized rule data to canonical strict-JSON text.

    Serialization is canonical: ``_FixedObject`` keeps its declared key
    order (used for rule-level fields), while plain mappings emit their
    string keys in Unicode code-point order at every nesting level.

    Values are restricted to strict JSON types: tuples and sets are
    rejected even though Python treats them as containers, non-finite
    numbers are rejected (strict JSON has no NaN/Infinity), and lone
    surrogates are rejected because the resulting text could not be
    encoded as UTF-8 for fingerprinting. Raises ValueError tagged
    ``non_json_value`` and never returns partially built text.
    """
    if value is None or isinstance(value, bool):
        return json.dumps(value, separators=(",", ":"), ensure_ascii=False)
    if isinstance(value, str):
        if any(0xD800 <= ord(ch) <= 0xDFFF for ch in value):
            raise _json_snapshot_error("a string with a lone surrogate")
        return json.dumps(value, separators=(",", ":"), ensure_ascii=False)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise _json_snapshot_error("a non-finite number")
        return json.dumps(value, separators=(",", ":"), allow_nan=False)
    if isinstance(value, _FixedObject):
        return "{" + ",".join(
            _canonical_json(key) + ":" + _canonical_json(val)
            for key, val in value.pairs
        ) + "}"
    if isinstance(value, Mapping):
        keys = list(value.keys())
        for key in keys:
            if not isinstance(key, str):
                raise _json_snapshot_error("a mapping with a non-string key")
        parts = []
        for key in sorted(keys):
            parts.append(_canonical_json(key) + ":" + _canonical_json(value[key]))
        return "{" + ",".join(parts) + "}"
    if isinstance(value, (list, tuple, set, frozenset)):
        if isinstance(value, (tuple, set, frozenset)):
            raise _json_snapshot_error(
                "a %s, which has no JSON representation"
                % type(value).__name__
            )
        return "[" + ",".join(_canonical_json(v) for v in value) + "]"
    raise _json_snapshot_error(
        "a value of type %s, which has no JSON representation"
        % type(value).__name__
    )


# --- static pattern analysis (used by PolicyGate.audit) ------------------
#
# A pattern is compiled to a tuple of tokens mirroring fnmatch.translate
# semantics exactly: ("star",) for `*`, or ("char", negated, ranges) for a
# single-character matcher, where ranges is a sorted tuple of inclusive
# (lo, hi) codepoint pairs describing the set as written (the set excluded
# when negated). `?` and literal characters are single-character matchers
# too. An empty positive range set never matches any character.

_FULL_RANGE = ((0, 0x10FFFF),)
_STAR = ("star",)
_ANY_CHAR = ("char", False, _FULL_RANGE)


def _normalize_ranges(ranges):
    """Sort inclusive (lo, hi) ranges and merge overlapping/adjacent ones."""
    merged = []
    for lo, hi in sorted(ranges):
        if merged and lo <= merged[-1][1] + 1:
            if hi > merged[-1][1]:
                merged[-1] = (merged[-1][0], hi)
        else:
            merged.append((lo, hi))
    return tuple(merged)


def _chars_to_ranges(chars):
    return _normalize_ranges((ord(c), ord(c)) for c in chars)


def _parse_class(pat, start):
    """Parse the ``[``-class at ``pat[start]`` like fnmatch.translate does.

    Returns ``(negated, ranges, next_index)``, or ``None`` when the ``[``
    is unterminated and fnmatch treats it as a literal character.
    """
    n = len(pat)
    j = start + 1
    if j < n and pat[j] == "!":
        j += 1
    if j < n and pat[j] == "]":
        j += 1
    while j < n and pat[j] != "]":
        j += 1
    if j >= n:
        return None
    body = pat[start + 1:j]
    nxt = j + 1
    if "-" not in body:
        if not body:
            return (False, (), nxt)  # empty range: never matches
        if body == "!":
            return (False, _FULL_RANGE, nxt)  # negated empty: any char
        negated = body[0] == "!"
        return (negated, _chars_to_ranges(body[1:] if negated else body), nxt)
    # Range-aware chunk processing, mirroring fnmatch.translate: dashes
    # found after the first body char split the body into chunks joined by
    # ranges; chunks whose range would be empty are merged away.
    chunks = []
    k = start + 3 if pat[start + 1] == "!" else start + 2
    i = start + 1
    while True:
        k = pat.find("-", k, j)
        if k < 0:
            break
        chunks.append(pat[i:k])
        i = k + 1
        k = k + 3
    chunk = pat[i:j]
    if chunk:
        chunks.append(chunk)
    else:
        chunks[-1] += "-"
    for m in range(len(chunks) - 1, 0, -1):
        if chunks[m - 1][-1] > chunks[m][0]:
            chunks[m - 1] = chunks[m - 1][:-1] + chunks[m][1:]
            del chunks[m]
    if chunks == [""]:
        return (False, (), nxt)  # empty range: never matches
    negated = chunks[0][0] == "!"
    if negated:
        chunks[0] = chunks[0][1:]
        if chunks == [""]:
            return (False, _FULL_RANGE, nxt)  # negated empty: any char
    ranges = []
    for m, chunk in enumerate(chunks):
        lo = 1 if m > 0 else 0
        hi = len(chunk) - 1 if m < len(chunks) - 1 else len(chunk)
        ranges.extend((ord(c), ord(c)) for c in chunk[lo:hi])
    for m in range(len(chunks) - 1):
        ranges.append((ord(chunks[m][-1]), ord(chunks[m + 1][0])))
    return (negated, _normalize_ranges(ranges), nxt)


def _tokenize_pattern(pat):
    """Compile a glob pattern to the token tuple used for overlap checks."""
    tokens = []
    i, n = 0, len(pat)
    while i < n:
        c = pat[i]
        if c == "*":
            tokens.append(_STAR)
            while i < n and pat[i] == "*":
                i += 1
        elif c == "?":
            tokens.append(_ANY_CHAR)
            i += 1
        elif c == "[":
            parsed = _parse_class(pat, i)
            if parsed is None:
                tokens.append(("char", False, _chars_to_ranges("[")))
                i += 1
            else:
                negated, ranges, i = parsed
                tokens.append(("char", negated, ranges))
        else:
            tokens.append(("char", False, _chars_to_ranges(c)))
            i += 1
    return tuple(tokens)


def _positive_ranges(token):
    """Positive codepoint ranges matched by a ("char", ...) token."""
    negated, ranges = token[1], token[2]
    if not negated:
        return ranges
    complement = []
    lo = 0
    for r_lo, r_hi in ranges:
        if r_lo > lo:
            complement.append((lo, r_lo - 1))
        lo = r_hi + 1
    if lo <= 0x10FFFF:
        complement.append((lo, 0x10FFFF))
    return tuple(complement)


def _ranges_intersect(r1, r2):
    i = j = 0
    while i < len(r1) and j < len(r2):
        if max(r1[i][0], r2[j][0]) <= min(r1[i][1], r2[j][1]):
            return True
        if r1[i][1] < r2[j][1]:
            i += 1
        else:
            j += 1
    return False


def _class_satisfiable(token):
    return bool(_positive_ranges(token))


def _classes_overlap(t1, t2):
    return _ranges_intersect(_positive_ranges(t1), _positive_ranges(t2))


def _token_min_char(token):
    """Smallest single character (by Unicode code point) a char token matches."""
    return chr(_positive_ranges(token)[0][0])


def _intersection_min_char(t1, t2):
    """Smallest character matched by both char tokens, or None if disjoint."""
    r1 = _positive_ranges(t1)
    r2 = _positive_ranges(t2)
    i = j = 0
    found = None
    while i < len(r1) and j < len(r2):
        lo = max(r1[i][0], r2[j][0])
        hi = min(r1[i][1], r2[j][1])
        if lo <= hi and (found is None or lo < found):
            found = lo
        if r1[i][1] < r2[j][1]:
            i += 1
        else:
            j += 1
    return chr(found) if found is not None else None


def _min_common_string(t1, t2):
    """Shortest string matching both tokenized patterns; ties broken by
    Unicode code-point lexicographic order.

    Mirrors :func:`_patterns_overlap` over the same token grid, but each
    reachable state stores the minimum witness suffix as a ``(length,
    text)`` pair (compared by length first, then text) instead of a mere
    boolean: a `*` may match the empty string, skip itself, or absorb one
    character demanded by a char token on the other side. A star/star
    alignment never needs to emit a character. Returns None only when the
    two patterns have no common string, which cannot happen for a pair
    whose overlap has already been established.
    """
    n1, n2 = len(t1), len(t2)
    best = [[None] * (n2 + 1) for _ in range(n1 + 1)]
    best[n1][n2] = (0, "")
    for j in range(n2 - 1, -1, -1):
        if t2[j][0] == "star":
            best[n1][j] = best[n1][j + 1]
    for i in range(n1 - 1, -1, -1):
        if t1[i][0] == "star":
            best[i][n2] = best[i + 1][n2]

    for i in range(n1 - 1, -1, -1):
        a = t1[i]
        a_star = a[0] == "star"
        for j in range(n2 - 1, -1, -1):
            b = t2[j]
            candidates = []
            if a_star:
                candidates.append(best[i + 1][j])  # a's '*' matches empty
                if b[0] == "star":
                    candidates.append(best[i][j + 1])
                elif _class_satisfiable(b):
                    tail = best[i][j + 1]  # a's '*' absorbs b's char
                    if tail is not None:
                        candidates.append(
                            (tail[0] + 1, _token_min_char(b) + tail[1])
                        )
            elif b[0] == "star":
                candidates.append(best[i][j + 1])  # b's '*' matches empty
                if _class_satisfiable(a):
                    tail = best[i + 1][j]  # b's '*' absorbs a's char
                    if tail is not None:
                        candidates.append(
                            (tail[0] + 1, _token_min_char(a) + tail[1])
                        )
            else:
                ch = _intersection_min_char(a, b)
                tail = best[i + 1][j + 1]
                if ch is not None and tail is not None:
                    candidates.append((tail[0] + 1, ch + tail[1]))
            candidates = [c for c in candidates if c is not None]
            best[i][j] = min(candidates) if candidates else None

    result = best[0][0]
    return None if result is None else result[1]


def _dimension_common_string(t1, t2, x1, x2):
    """Shortest string matching both rules' positive token patterns for
    one selector dimension while matching neither rule's exclusion
    pattern (``None`` means the rule declares no exclusion); ties broken
    by Unicode code-point lexicographic order. Returns None when no
    string qualifies, in which case the audited pair cannot overlap on
    this dimension.

    Without exclusions on either side this is exactly the legacy
    overlap check plus :func:`_min_common_string`, so rules that never
    use selector exclusions keep their previous witnesses byte for
    byte.
    """
    if x1 is None and x2 is None:
        if not _patterns_overlap(t1, t2):
            return None
        return _min_common_string(t1, t2)
    negatives = [tokens for tokens in (x1, x2) if tokens is not None]
    return _min_string_avoiding([t1, t2], negatives)


def _pattern_satisfiable(tokens):
    """True iff the tokenized pattern matches at least one string."""
    return all(
        token[0] == "star" or _class_satisfiable(token) for token in tokens
    )


def _min_pattern_string(tokens):
    """Shortest string matching one tokenized pattern; ties (impossible
    here, each position is forced) would break by Unicode code point.

    Every ``char`` token must consume exactly one character, so the
    shortest match takes the smallest code point each token accepts and
    every ``*`` matches empty. Returns None when the pattern matches no
    string at all (an empty character class).
    """
    chars = []
    for token in tokens:
        if token[0] == "char":
            positive = _positive_ranges(token)
            if not positive:
                return None
            chars.append(chr(positive[0][0]))
    return "".join(chars)


def _min_string_avoiding(positives, negatives):
    """Shortest string matching every tokenized pattern in ``positives``
    and no tokenized pattern in ``negatives``; ties broken by Unicode
    code-point lexicographic order. Returns None when no string qualifies.

    Each token list is simulated as the NFA fnmatch.translate implies:
    states are token positions, a ``*`` has an epsilon move to the next
    position and consumes any character while staying put, a char token
    consumes one character in its positive ranges. The search is a BFS
    over the product of per-pattern reachable state sets; characters are
    enumerated by elementary code-point intervals (every character in one
    interval triggers the same transition, so the interval's smallest
    character represents it) in increasing order, which makes the first
    accepting joint state discovered the (length, lexicographic) minimum.
    A joint state accepts when every positive pattern has consumed all
    its tokens and no negative pattern has.
    """
    nfas = []
    for tokens in positives:
        nfas.append((tokens, True))
    for tokens in negatives:
        nfas.append((tokens, False))
    compiled = []
    for tokens, _is_positive in nfas:
        stars = 0
        chars = []
        for i, token in enumerate(tokens):
            if token[0] == "star":
                stars |= 1 << i
            else:
                chars.append((i, _positive_ranges(token)))
        compiled.append((len(tokens), stars, tuple(chars)))

    def closure(kind, state):
        _n, stars, _chars = compiled[kind]
        while True:
            nxt = state | ((state & stars) << 1)
            if nxt == state:
                return state
            state = nxt

    start = tuple(closure(kind, 1) for kind in range(len(compiled)))

    def accepting(joint):
        for kind, (_tokens, is_positive) in enumerate(nfas):
            done = (joint[kind] >> compiled[kind][0]) & 1
            if is_positive:
                if not done:
                    return False
            elif done:
                return False
        return True

    visited = {start}
    queue = deque([(start, "")])
    while queue:
        joint, text = queue.popleft()
        if accepting(joint):
            return text
        boundaries = {0}
        for kind in range(len(compiled)):
            _n, _stars, chars = compiled[kind]
            for i, ranges in chars:
                if (joint[kind] >> i) & 1:
                    for lo, hi in ranges:
                        boundaries.add(lo)
                        boundaries.add(min(hi + 1, 0x110000))
        ordered = sorted(boundaries)
        representatives = []
        for pos, lo in enumerate(ordered):
            hi = ordered[pos + 1] - 1 if pos + 1 < len(ordered) else 0x10FFFF
            if lo <= min(hi, 0x10FFFF):
                representatives.append(lo)
        for codepoint in representatives:
            nxt = []
            for kind in range(len(compiled)):
                _n, stars, chars = compiled[kind]
                state = joint[kind]
                stepped = state & stars  # a '*' consumes the char and stays
                for i, ranges in chars:
                    if (state >> i) & 1 and _ranges_contain(ranges, codepoint):
                        stepped |= 1 << (i + 1)
                nxt.append(closure(kind, stepped))
            nxt = tuple(nxt)
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, text + chr(codepoint)))
    return None


def _ranges_contain(ranges, codepoint):
    for lo, hi in ranges:
        if lo <= codepoint <= hi:
            return True
        if codepoint < lo:
            return False
    return False


def _value_matches_pattern(value, pattern):
    # A pattern constraint only matches string tag values; anything else
    # (including a missing key, surfaced as a non-string here) fails.
    return isinstance(value, str) and fnmatch.fnmatchcase(value, pattern)


def _tag_constraints_compatible(r1, r2, tp1, tp2, te1, te2):
    """True iff one tag assignment can satisfy both rules' constraints.

    ``tp1``/``tp2`` are the rules' ``tag_patterns`` values compiled by
    :func:`_tokenize_pattern`; ``te1``/``te2`` are their compiled
    ``tag_exclude_patterns``. Constraints on disjoint keys are jointly
    satisfiable (the caller may supply extra tags). On a shared key, two
    exact values conflict only when unequal, an exact value must match
    the pattern, and two patterns need one common string. A pattern
    matching no string at all makes its own rule unsatisfiable, so no
    request can match both rules. Exclusion constraints further require
    the key's value to avoid every ``tag_exclude_patterns`` pattern
    declared for it by either rule: an exact value fails when it is a
    string hitting an exclusion pattern, and a pattern- or
    exclusion-only key needs one string that satisfies its positive
    patterns (if any) while matching none of the exclusion patterns.
    Presence constraints only look at the key: one rule requiring a key
    the other rule forbids is unsatisfiable, and a key either rule
    forbids must not be forced present by the other rule's exact or
    pattern constraints (an exclusion alone never forces presence, so a
    forbidden key simply stays absent and passes every exclusion).
    """
    tags1, pats1 = r1["tags"], r1["tag_patterns"]
    tags2, pats2 = r2["tags"], r2["tag_patterns"]
    pres1, pres2 = r1["tag_presence"], r2["tag_presence"]
    forbidden = set()
    for key, required in pres1.items():
        if key in pres2 and pres2[key] != required:
            return False
        if not required:
            forbidden.add(key)
    for key, required in pres2.items():
        if not required:
            forbidden.add(key)
    for key in forbidden:
        if key in tags1 or key in tags2 or key in pats1 or key in pats2:
            return False
    for tokens in tp1.values():
        if not _pattern_satisfiable(tokens):
            return False
    for tokens in tp2.values():
        if not _pattern_satisfiable(tokens):
            return False
    for key, value in tags1.items():
        if key in tags2:
            if tags2[key] != value:
                return False
        elif key in pats2 and not _value_matches_pattern(value, pats2[key]):
            return False
    for key, value in tags2.items():
        if key in pats1 and not _value_matches_pattern(value, pats1[key]):
            return False
    for key in pats1:
        if key in pats2 and not _patterns_overlap(tp1[key], tp2[key]):
            return False
    for key in set(te1) | set(te2):
        if key in forbidden:
            # The key stays absent, which passes every exclusion.
            continue
        if key in tags1 or key in tags2:
            value = tags1[key] if key in tags1 else tags2[key]
            for rule in (r1, r2):
                pattern = rule["tag_exclude_patterns"].get(key)
                if pattern is not None and _value_matches_pattern(
                    value, pattern
                ):
                    return False
        else:
            positives = []
            if key in pats1:
                positives.append(tp1[key])
            if key in pats2:
                positives.append(tp2[key])
            negatives = []
            if key in te1:
                negatives.append(te1[key])
            if key in te2:
                negatives.append(te2[key])
            if _min_string_avoiding(positives, negatives) is None:
                return False
    return True


def _witness_tags(r1, r2, tp1, tp2, te1, te2):
    """Joint tag assignment satisfying both rules' tag constraints.

    Only keys constrained by one of the two rules appear — whether in
    ``tags``, ``tag_patterns``, ``tag_exclude_patterns`` or
    ``tag_presence`` — emitted in Unicode code-point order. An exact
    constraint pins the value (a shared exact/pattern key takes the
    exact value, which the compatibility check has already proven to
    match every positive pattern and avoid every exclusion); a key
    constrained only by patterns and exclusions takes the shortest
    string satisfying every positive pattern on it and matching none of
    its exclusion patterns, ties broken by Unicode code-point
    lexicographic order. A key either rule's ``tag_presence`` forbids
    is never written (its absence satisfies every exclusion on it); a
    key only required to exist, with no exact, pattern or exclusion
    constraint from either rule, takes the shortest string satisfying
    both sides' conditions — the empty string. Exact values
    are deep-copied (direct construction permits mutable tag values) so
    a caller mutating a returned report can never touch the loaded rules
    or later reports.
    """
    keys = (
        set(r1["tags"])
        | set(r1["tag_patterns"])
        | set(r1["tag_exclude_patterns"])
        | set(r1["tag_presence"])
        | set(r2["tags"])
        | set(r2["tag_patterns"])
        | set(r2["tag_exclude_patterns"])
        | set(r2["tag_presence"])
    )
    forbidden = {
        key
        for rule in (r1, r2)
        for key, required in rule["tag_presence"].items()
        if not required
    }
    merged = {}
    for key in keys:
        if key in forbidden:
            continue
        exact = None
        have_exact = False
        patterns = []
        negatives = []
        for rule, compiled, excluded in ((r1, tp1, te1), (r2, tp2, te2)):
            if key in rule["tags"]:
                have_exact = True
                exact = rule["tags"][key]
            elif key in rule["tag_patterns"]:
                patterns.append(compiled[key])
            if key in rule["tag_exclude_patterns"]:
                negatives.append(excluded[key])
        if have_exact:
            merged[key] = copy.deepcopy(exact)
        elif negatives:
            merged[key] = _min_string_avoiding(patterns, negatives)
        elif len(patterns) == 1:
            merged[key] = _min_pattern_string(patterns[0])
        elif patterns:
            merged[key] = _min_common_string(patterns[0], patterns[1])
        else:
            # Presence-only key: the shortest string is the empty one.
            merged[key] = ""
    return {key: merged[key] for key in sorted(merged)}


def _pair_witness(r1, r2, c1, c2, dimensions):
    """Minimum request matching both selectors of one audited pair.

    ``dimensions`` holds the per-dimension witness strings already
    computed by :func:`_audit_pair` (each satisfies both rules' positive
    patterns and avoids both rules' exclusion patterns).
    """
    return {
        "subject": dimensions[0],
        "action": dimensions[1],
        "resource": dimensions[2],
        "tags": _witness_tags(r1, r2, c1[6], c2[6], c1[7], c2[7]),
    }


def _patterns_overlap(t1, t2):
    """True iff some string matches both tokenized glob patterns.

    Dynamic programming over the token grid: dp[i][j] is True when the
    suffixes t1[i:] and t2[j:] can match a common string. `*` either
    matches empty or absorbs one character matched by the other side.
    """
    n1, n2 = len(t1), len(t2)
    star1 = [True] * (n1 + 1)
    for i in range(n1 - 1, -1, -1):
        star1[i] = star1[i + 1] and t1[i][0] == "star"
    star2 = [True] * (n2 + 1)
    for j in range(n2 - 1, -1, -1):
        star2[j] = star2[j + 1] and t2[j][0] == "star"

    row = bytearray(star2)  # row i == n1: t1 exhausted, t2[j:] must be stars
    for i in range(n1 - 1, -1, -1):
        cur = bytearray(n2 + 1)
        cur[n2] = star1[i]
        a = t1[i]
        a_star = a[0] == "star"
        for j in range(n2 - 1, -1, -1):
            b = t2[j]
            if a_star and b[0] == "star":
                cur[j] = cur[j + 1] or row[j]
            elif a_star:
                cur[j] = row[j] or (_class_satisfiable(b) and cur[j + 1])
            elif b[0] == "star":
                cur[j] = cur[j + 1] or (_class_satisfiable(a) and row[j])
            else:
                cur[j] = _classes_overlap(a, b) and row[j + 1]
        row = cur
    return bool(row[0])


def _unsatisfiable_finding(rule, reason):
    """The fixed-shape finding for one unreachable rule."""
    return {
        "code": "unsatisfiable_rule",
        "severity": "error",
        "rule": rule["id"],
        "other_rule": None,
        "winner": None,
        "shadowed": None,
        "reason": reason,
        "witness": None,
    }


def _audit_rule(rule, compiled):
    """Build the unsatisfiable-rule finding for one rule, or None.

    A rule is unreachable when no request can ever match it. Each
    string dimension needs at least one string matching its positive
    pattern; when the dimension declares an exclusion, some string must
    match the positive pattern without hitting the exclusion pattern.
    Every ``tag_patterns`` pattern likewise needs at least one matching
    string. Exact ``tags``, ``tag_presence`` and
    ``tag_exclude_patterns`` can always be satisfied on their own — a
    forbidden or exclusion-only key simply stays absent — so they never
    make a rule unreachable. Only the first failing field is reported;
    fields are probed in the Unicode code-point order of their names
    (action, resource, subject, tag_patterns), and within
    ``tag_patterns`` the keys are probed in Unicode code-point order.
    """
    for field, positive, negative in (
        ("action", compiled[1], compiled[4]),
        ("resource", compiled[2], compiled[5]),
        ("subject", compiled[0], compiled[3]),
    ):
        if not _pattern_satisfiable(positive):
            reason = (
                "rule %r can never match: no string matches the %s "
                "pattern %r" % (rule["id"], field, rule[field])
            )
        elif negative is not None and (
            _min_string_avoiding([positive], [negative]) is None
        ):
            reason = (
                "rule %r can never match: every string matching the %s "
                "pattern %r is excluded by %s %r"
                % (
                    rule["id"],
                    field,
                    rule[field],
                    field + "_exclude",
                    rule[field + "_exclude"],
                )
            )
        else:
            continue
        return _unsatisfiable_finding(rule, reason)
    for key in sorted(rule["tag_patterns"]):
        if not _pattern_satisfiable(compiled[6][key]):
            return _unsatisfiable_finding(
                rule,
                "rule %r can never match: no string matches the "
                "tag_patterns pattern %r for key %r"
                % (rule["id"], rule["tag_patterns"][key], key),
            )
    return None


def _audit_pair(r1, r2, c1, c2):
    """Build the finding for one rule pair, or None when there is none."""
    dimensions = []
    for dim in range(3):
        witness = _dimension_common_string(
            c1[dim], c2[dim], c1[3 + dim], c2[3 + dim]
        )
        if witness is None:
            return None
        dimensions.append(witness)
    if not _tag_constraints_compatible(r1, r2, c1[6], c2[6], c1[7], c2[7]):
        return None

    identical = (
        r1["subject"] == r2["subject"]
        and r1["action"] == r2["action"]
        and r1["resource"] == r2["resource"]
        and r1["subject_exclude"] == r2["subject_exclude"]
        and r1["action_exclude"] == r2["action_exclude"]
        and r1["resource_exclude"] == r2["resource_exclude"]
        and r1["tags"] == r2["tags"]
        and r1["tag_patterns"] == r2["tag_patterns"]
        and r1["tag_exclude_patterns"] == r2["tag_exclude_patterns"]
        and r1["tag_presence"] == r2["tag_presence"]
    )
    if identical:
        # Identical selectors: one rule can never win, so it is shadowed.
        if r1["effect"] != r2["effect"]:
            winner = r1 if r1["effect"] == "deny" else r2
            severity = "error"
        else:
            # r1 is declared earlier, so it wins priority ties.
            winner = r1 if r1["priority"] >= r2["priority"] else r2
            severity = "warning"
        loser = r2 if winner is r1 else r1
        if severity == "error":
            reason = (
                "rule %r is fully shadowed by deny rule %r: identical "
                "selectors, and explicit deny overrides allow"
                % (loser["id"], winner["id"])
            )
        else:
            reason = (
                "rule %r is fully shadowed by rule %r: identical "
                "selectors, and priority then declaration order always "
                "prefer %r" % (loser["id"], winner["id"], winner["id"])
            )
        return {
            "code": "shadowed_rule",
            "severity": severity,
            "rule": r1["id"],
            "other_rule": r2["id"],
            "winner": winner["id"],
            "shadowed": loser["id"],
            "reason": reason,
            "witness": _pair_witness(r1, r2, c1, c2, dimensions),
        }

    if r1["effect"] != r2["effect"]:
        deny = r1 if r1["effect"] == "deny" else r2
        allow = r2 if deny is r1 else r1
        return {
            "code": "effect_overlap",
            "severity": "error",
            "rule": r1["id"],
            "other_rule": r2["id"],
            "winner": deny["id"],
            "shadowed": None,
            "reason": (
                "selectors overlap; explicit deny rule %r overrides allow "
                "rule %r for every request matching both, regardless of "
                "priority" % (deny["id"], allow["id"])
            ),
            "witness": _pair_witness(r1, r2, c1, c2, dimensions),
        }

    # Same-effect partial overlap is not a conflict.
    return None


class PolicyGate:
    """Offline policy evaluator.

    Rules are fully validated at construction time; decide() only performs
    deterministic matching over the normalized rule list.
    """

    def __init__(self, rules):
        if not isinstance(rules, (list, tuple)):
            raise ValueError("rules must be a sequence of rule mappings")
        # Rules are validated and copied into a local list that is
        # published as self.rules only once every rule has fully
        # succeeded. A failure mid-way therefore leaves no partially
        # populated instance behind.
        normalized = []
        seen_ids = set()
        for i, r in enumerate(rules):
            if not isinstance(r, dict):
                raise ValueError("rule %d: rule must be a mapping" % i)

            effect = r.get("effect")
            if effect not in ("allow", "deny"):
                raise ValueError(
                    "rule %d: field 'effect' must be 'allow' or 'deny'" % i
                )

            rid = r.get("id", str(i))
            if not isinstance(rid, str) or not rid:
                raise ValueError(
                    "rule %d: field 'id' must be a non-empty string" % i
                )
            if rid in seen_ids:
                raise ValueError("rule %d: duplicate id %r" % (i, rid))
            seen_ids.add(rid)

            priority = r.get("priority", 0)
            if not isinstance(priority, int) or isinstance(priority, bool):
                raise ValueError(
                    "rule %d: field 'priority' must be a non-boolean integer" % i
                )

            for field in _STRING_FIELDS:
                if not isinstance(r.get(field, "*"), str):
                    raise ValueError(
                        "rule %d: field %r must be a string" % (i, field)
                    )

            for field in _EXCLUSION_FIELDS:
                if field in r and not isinstance(r[field], str):
                    raise ValueError(
                        "invalid_selector_exclusion: rule %d: field %r "
                        "must be a string when provided" % (i, field)
                    )

            tags = r.get("tags", {})
            if not isinstance(tags, dict) or not all(
                isinstance(k, str) for k in tags
            ):
                raise ValueError(
                    "rule %d: field 'tags' must be a mapping with string keys" % i
                )

            tag_patterns = r.get("tag_patterns", {})
            if (
                not isinstance(tag_patterns, dict)
                or not all(isinstance(k, str) for k in tag_patterns)
                or not all(isinstance(v, str) for v in tag_patterns.values())
            ):
                raise ValueError(
                    "invalid_tag_patterns: rule %d: field 'tag_patterns' "
                    "must be a mapping with string keys and string pattern "
                    "values" % i
                )

            shared_tag_keys = sorted(set(tags) & set(tag_patterns))
            if shared_tag_keys:
                raise ValueError(
                    "tag_constraint_conflict: rule %d: key %r appears in "
                    "both 'tags' and 'tag_patterns'" % (i, shared_tag_keys[0])
                )

            tag_exclude_patterns = r.get("tag_exclude_patterns", {})
            if (
                not isinstance(tag_exclude_patterns, dict)
                or not all(isinstance(k, str) for k in tag_exclude_patterns)
                or not all(
                    isinstance(v, str) for v in tag_exclude_patterns.values()
                )
            ):
                raise ValueError(
                    "invalid_tag_exclude_patterns: rule %d: field "
                    "'tag_exclude_patterns' must be a mapping with string "
                    "keys and string pattern values" % i
                )

            shared_exclude_keys = sorted(
                (set(tags) | set(tag_patterns)) & set(tag_exclude_patterns)
            )
            if shared_exclude_keys:
                key = shared_exclude_keys[0]
                other = "tags" if key in tags else "tag_patterns"
                raise ValueError(
                    "tag_constraint_conflict: rule %d: key %r appears in "
                    "both %r and 'tag_exclude_patterns'" % (i, key, other)
                )

            tag_presence = r.get("tag_presence", {})
            if (
                not isinstance(tag_presence, dict)
                or not all(isinstance(k, str) for k in tag_presence)
                or not all(isinstance(v, bool) for v in tag_presence.values())
            ):
                raise ValueError(
                    "invalid_tag_presence: rule %d: field 'tag_presence' "
                    "must be a mapping with string keys and boolean "
                    "values" % i
                )

            shared_presence_keys = sorted(
                (set(tags) | set(tag_patterns) | set(tag_exclude_patterns))
                & set(tag_presence)
            )
            if shared_presence_keys:
                key = shared_presence_keys[0]
                if key in tags:
                    other = "tags"
                elif key in tag_patterns:
                    other = "tag_patterns"
                else:
                    other = "tag_exclude_patterns"
                raise ValueError(
                    "tag_presence_conflict: rule %d: key %r appears in "
                    "both %r and 'tag_presence'" % (i, key, other)
                )

            unsupported = set(r) - _ALLOWED_FIELDS
            if unsupported:
                raise ValueError(
                    "rule %d: unsupported field %r" % (i, sorted(unsupported)[0])
                )

            # All conventional validation has passed for this rule; only
            # now take independent deep copies of the caller-owned
            # mappings (and every nested value inside them) so the
            # normalized rule can never alias data the caller might mutate
            # afterwards. An un-copyable value aborts before anything is
            # stored, so no partially copied rule ever escapes.
            tags = _deepcopy_rule_mapping(tags, i, "tags")
            tag_patterns = _deepcopy_rule_mapping(
                tag_patterns, i, "tag_patterns"
            )
            tag_exclude_patterns = _deepcopy_rule_mapping(
                tag_exclude_patterns, i, "tag_exclude_patterns"
            )
            tag_presence = _deepcopy_rule_mapping(
                tag_presence, i, "tag_presence"
            )

            normalized.append(
                {
                    "id": rid,
                    "effect": effect,
                    "priority": priority,
                    "subject": r.get("subject", "*"),
                    "action": r.get("action", "*"),
                    "resource": r.get("resource", "*"),
                    "subject_exclude": r.get("subject_exclude"),
                    "action_exclude": r.get("action_exclude"),
                    "resource_exclude": r.get("resource_exclude"),
                    "tags": tags,
                    "tag_patterns": tag_patterns,
                    "tag_exclude_patterns": tag_exclude_patterns,
                    "tag_presence": tag_presence,
                    "_index": i,
                }
            )

        # Every rule validated and copied successfully; only now does the
        # gate take ownership, so construction can never expose a
        # half-populated instance.
        self.rules = normalized
        # Directly constructed gates carry no document envelope; only
        # from_json() with a versioned document object sets this to the
        # supported version (see from_json).
        self.document_version = None

    @staticmethod
    def _validate_document_envelope(root):
        """Validate a versioned document object and extract its payload.

        Returns ``(rules, fingerprint)`` with ``fingerprint`` None when the
        optional field is omitted. Envelope problems raise
        :class:`PolicyConfigError` in the fixed precedence
        ``unknown_document_field``, ``missing_version``,
        ``invalid_version``, ``unsupported_version``, ``missing_rules``,
        ``rules_not_array``, ``invalid_fingerprint``; the first problem
        found aborts the load. ``fingerprint_mismatch`` is checked by the
        caller once the rules have loaded and their canonical snapshot
        fingerprint can be computed.
        """
        unknown = [key for key in root if key not in _DOCUMENT_FIELDS]
        if unknown:
            raise PolicyConfigError(
                "unknown_document_field",
                "document contains unknown field %r" % unknown[0],
            )
        if "version" not in root:
            raise PolicyConfigError(
                "missing_version",
                "document is missing required field 'version'",
            )
        version = root["version"]
        if not isinstance(version, int) or isinstance(version, bool):
            raise PolicyConfigError(
                "invalid_version",
                "document field 'version' must be an integer, got %s"
                % type(version).__name__,
            )
        if version != _SUPPORTED_DOCUMENT_VERSION:
            raise PolicyConfigError(
                "unsupported_version",
                "document version %d is not supported" % version,
            )
        if "rules" not in root:
            raise PolicyConfigError(
                "missing_rules",
                "document is missing required field 'rules'",
            )
        rules = root["rules"]
        if not isinstance(rules, list):
            raise PolicyConfigError(
                "rules_not_array",
                "document field 'rules' must be an array, got %s"
                % type(rules).__name__,
            )
        fingerprint = None
        if "fingerprint" in root:
            fingerprint = root["fingerprint"]
            if (
                not isinstance(fingerprint, str)
                or len(fingerprint) != 64
                or not set(fingerprint) <= _FINGERPRINT_ALPHABET
            ):
                raise PolicyConfigError(
                    "invalid_fingerprint",
                    "document field 'fingerprint' must be a 64-character "
                    "lowercase hexadecimal SHA-256 digest",
                )
        return rules, fingerprint

    @classmethod
    def from_json(cls, document):
        """Build a gate from a JSON text document.

        ``document`` must be a ``str`` whose root JSON value is either a
        legacy array of rule objects or a versioned document object. A
        document object may only carry the keys ``version``, ``rules`` and
        ``fingerprint``: ``version`` is required and must be the integer
        ``1``, ``rules`` is required and must be the rule array, and
        ``fingerprint`` is optional but, when provided, must be the
        64-character lowercase hexadecimal SHA-256 digest of the rules'
        canonical snapshot (exactly what :meth:`fingerprint` computes).
        Loading performs no decisions, no I/O and never mutates the input
        text; on failure no partially built instance escapes this method.

        Structural JSON problems raise :class:`PolicyConfigError` with a
        ``code`` of ``invalid_json``, ``duplicate_key``,
        ``root_not_array_or_object`` or ``rule_not_object``; envelope
        problems on a document object raise ``unknown_document_field``,
        ``missing_version``, ``invalid_version``, ``unsupported_version``,
        ``missing_rules``, ``rules_not_array``, ``invalid_fingerprint`` or
        ``fingerprint_mismatch`` (checked in that order, first error
        wins); semantic rule errors raise ``ValueError`` exactly like the
        direct constructor (naming the first bad index).

        A gate loaded from a versioned document has ``document_version``
        set to ``1``; a gate loaded from a legacy array or built directly
        has ``document_version`` ``None``.
        """
        if not isinstance(document, str):
            raise TypeError("document must be a JSON text string")

        try:
            root = json.loads(
                document,
                object_pairs_hook=_reject_duplicate_keys,
                parse_constant=_reject_constant,
            )
        except _DuplicateKeyError as exc:
            raise PolicyConfigError(
                "duplicate_key", "duplicate key %r in JSON object" % str(exc)
            ) from None
        except (json.JSONDecodeError, ValueError) as exc:
            raise PolicyConfigError(
                "invalid_json", "document is not valid JSON: %s" % exc
            ) from None

        if isinstance(root, list):
            rules = root
            document_fingerprint = None
        elif isinstance(root, dict):
            rules, document_fingerprint = cls._validate_document_envelope(root)
        else:
            raise PolicyConfigError(
                "root_not_array_or_object",
                "root JSON value must be an array or an object, got %s"
                % type(root).__name__,
            )
        for i, rule in enumerate(rules):
            if not isinstance(rule, dict):
                raise PolicyConfigError(
                    "rule_not_object",
                    "rule %d: array element must be a JSON object, got %s"
                    % (i, type(rule).__name__),
                )

        gate = cls(rules)
        if isinstance(root, dict):
            # The declared digest must commit to exactly the rules that
            # loaded; the canonical snapshot fingerprint is computed only
            # now, once semantic rule validation has fully succeeded.
            if (
                document_fingerprint is not None
                and document_fingerprint != gate.fingerprint()
            ):
                raise PolicyConfigError(
                    "fingerprint_mismatch",
                    "document fingerprint does not match the canonical "
                    "fingerprint of the loaded rules",
                )
            gate.document_version = _SUPPORTED_DOCUMENT_VERSION
        return gate

    # --- canonical snapshot export ------------------------------------

    _SNAPSHOT_FIELDS = (
        "id",
        "effect",
        "priority",
        "subject",
        "action",
        "resource",
    )

    def _rule_snapshot_object(self, rule):
        """One rule's normalized snapshot as a fixed-order ``_FixedObject``.

        Only the effective fields are emitted, in fixed order, so the
        internal ``_index`` never leaks; each provided selector
        exclusion is emitted in its fixed order immediately after
        ``resource`` (an omitted field, stored as ``None``, is never
        written, while an explicitly provided empty string is), then
        ``tags``, followed by non-empty ``tag_patterns``,
        ``tag_exclude_patterns`` and ``tag_presence`` mappings in that
        order. Shared by :meth:`_snapshot` and
        :meth:`rule_change_report` so both views always agree.
        """
        pairs = [(field, rule[field]) for field in self._SNAPSHOT_FIELDS]
        for field in _EXCLUSION_FIELDS:
            if rule[field] is not None:
                pairs.append((field, rule[field]))
        pairs.append(("tags", rule["tags"]))
        if rule["tag_patterns"]:
            pairs.append(("tag_patterns", rule["tag_patterns"]))
        if rule["tag_exclude_patterns"]:
            pairs.append(("tag_exclude_patterns", rule["tag_exclude_patterns"]))
        if rule["tag_presence"]:
            pairs.append(("tag_presence", rule["tag_presence"]))
        return _FixedObject(pairs)

    @staticmethod
    def _materialize_snapshot(value):
        """Convert canonical snapshot structures into plain JSON values.

        ``_FixedObject`` keeps its declared pair order; plain mappings
        are rebuilt with their string keys in Unicode code-point order,
        exactly mirroring :func:`_canonical_json`'s nested-key sorting;
        lists keep their element order. Every container is rebuilt
        recursively, so a materialized report shares no mutable container
        with the loaded rules. Leaves are strict-JSON scalars (the
        snapshot has already been through :func:`_canonical_json`).
        """
        if isinstance(value, _FixedObject):
            return {
                key: PolicyGate._materialize_snapshot(val)
                for key, val in value.pairs
            }
        if isinstance(value, Mapping):
            return {
                key: PolicyGate._materialize_snapshot(value[key])
                for key in sorted(value.keys())
            }
        if isinstance(value, list):
            return [PolicyGate._materialize_snapshot(val) for val in value]
        return value

    def _snapshot(self):
        """Normalized rules ready for canonical JSON serialization.

        The copy is shallow, and only read by the serializer, so neither
        the rules nor caller-provided mappings are mutated.
        """
        return [self._rule_snapshot_object(rule) for rule in self.rules]

    def to_json(self):
        """Export the loaded rules as canonical strict-JSON text.

        For a gate built directly or loaded from a legacy array, the root
        value is an array preserving declaration order (a gate loaded
        from a versioned document exports the envelope described below).
        Every
        rule writes its normalized, actually-effective ``id``, ``effect``,
        ``priority``, ``subject``, ``action``, ``resource`` and ``tags``
        in that fixed order, so all defaults appear explicitly and no
        internal index leaks; each provided ``subject_exclude``,
        ``action_exclude`` and ``resource_exclude`` is written in that
        fixed field order immediately after ``resource`` (an omitted
        field is never written, an explicitly provided empty string is),
        a rule with a non-empty ``tag_patterns``
        mapping writes it in the same fixed order immediately after
        ``tags``, a rule with a non-empty ``tag_exclude_patterns``
        mapping writes it immediately after that, and a rule with a
        non-empty ``tag_presence`` mapping writes it immediately after
        that, while rules without
        pattern or presence constraints export exactly the same bytes
        as before. Tag objects (at every nesting level)
        have their keys sorted by Unicode code point; separators are
        compact and non-ASCII characters are emitted unescaped. An empty
        rule set exports as ``[]`` and repeated calls return identical
        text while the rules are unchanged.

        When the gate was loaded from a versioned document object
        (``document_version`` is not ``None``), the root value is instead
        a canonical object with the fixed key order ``version``,
        ``rules``, ``fingerprint``: ``rules`` holds the same canonical
        rule array a legacy gate would export, and ``fingerprint`` is the
        rules snapshot's SHA-256 digest, so a digest provided at load
        time is preserved byte for byte. Gates built directly or loaded
        from a legacy array keep exporting the bare canonical array.

        The result reloads losslessly through :meth:`from_json` with
        identical decide/explain/decide_many/audit behavior. A value that
        cannot be represented losslessly in strict JSON (a tuple, set,
        non-finite number, nested mapping with non-string keys, or a
        string that cannot be UTF-8 encoded) raises ``ValueError`` whose
        message carries the fixed tag ``non_json_value``; no partial text
        is returned. Performs no I/O.
        """
        snapshot = self._snapshot()
        rules_text = _canonical_json(snapshot)
        if self.document_version is None:
            return rules_text
        digest = hashlib.sha256(rules_text.encode("utf-8")).hexdigest()
        return _canonical_json(
            _FixedObject(
                [
                    ("version", self.document_version),
                    ("rules", snapshot),
                    ("fingerprint", digest),
                ]
            )
        )

    def fingerprint(self):
        """SHA-256 hex digest of the canonical rules snapshot's UTF-8 bytes.

        Uses exactly the same rules snapshot as :meth:`to_json` — the
        canonical rule array, without any versioned-document envelope —
        so the digest is identical whether the gate was built directly,
        loaded from a legacy array or loaded from a versioned document,
        and always matches the ``fingerprint`` field a versioned document
        commits to. The result is a 64-character lowercase hex
        string. A snapshot that cannot be serialized or UTF-8 encoded
        raises the same ``ValueError`` tagged ``non_json_value``.
        Performs no I/O.
        """
        rules_text = _canonical_json(self._snapshot())
        return hashlib.sha256(rules_text.encode("utf-8")).hexdigest()

    @staticmethod
    def _tags_match(rule, tags):
        # Exact constraints compare values for equality; pattern
        # constraints apply fnmatch.fnmatchcase to the request's tag
        # value, so a missing key or a non-string value simply means the
        # rule does not match. Exclusion constraints invert the pattern
        # test: a missing key, a non-string value or a value that does
        # not match the exclusion pattern all pass, and only an actual
        # hit makes the rule not match. Presence constraints only look at
        # the key: a ``True`` entry demands the key exist (its value may
        # be of any type), a ``False`` entry demands it be absent.
        return (
            all(tags.get(k) == v for k, v in rule["tags"].items())
            and all(
                _value_matches_pattern(tags.get(k), pattern)
                for k, pattern in rule["tag_patterns"].items()
            )
            and all(
                not _value_matches_pattern(tags.get(k), pattern)
                for k, pattern in rule["tag_exclude_patterns"].items()
            )
            and all(
                (k in tags) == required
                for k, required in rule["tag_presence"].items()
            )
        )

    @staticmethod
    def _dimension_matches(value, pattern, exclude):
        # A request dimension hits the rule when the positive selector
        # matches and the value escapes the exclusion pattern; an omitted
        # exclusion (None) excludes nothing, while an empty-string
        # exclusion keeps its real fnmatch.fnmatchcase semantics (it only
        # matches, and therefore excludes, the empty string).
        return fnmatch.fnmatchcase(value, pattern) and (
            exclude is None or not fnmatch.fnmatchcase(value, exclude)
        )

    @staticmethod
    def _matches(rule, subject, action, resource, tags):
        return (
            PolicyGate._dimension_matches(
                subject, rule["subject"], rule["subject_exclude"]
            )
            and PolicyGate._dimension_matches(
                action, rule["action"], rule["action_exclude"]
            )
            and PolicyGate._dimension_matches(
                resource, rule["resource"], rule["resource_exclude"]
            )
            and PolicyGate._tags_match(rule, tags)
        )

    @staticmethod
    def _check_inputs(subject, action, resource, tags):
        for name, value in (
            ("subject", subject),
            ("action", action),
            ("resource", resource),
        ):
            if not isinstance(value, str):
                raise TypeError("%s must be a string" % name)
        if tags is None:
            tags = {}
        elif not isinstance(tags, Mapping):
            raise TypeError("tags must be a mapping or None")
        return tags

    @staticmethod
    def _select(matched):
        """Pick the winning rule out of the matched ones.

        Explicit deny always wins; within one effect, higher priority wins,
        then the earliest declaration order breaks ties deterministically.
        Returns (decision, winner rule or None).
        """
        denies = [r for r in matched if r["effect"] == "deny"]
        allows = [r for r in matched if r["effect"] == "allow"]

        winners = denies if denies else allows
        if not winners:
            return (
                {"effect": "deny", "rule": None, "reason": "default deny"},
                None,
            )

        winner = min(winners, key=lambda r: (-r["priority"], r["_index"]))
        reason = "matched %s rule %r (priority %d)" % (
            winner["effect"],
            winner["id"],
            winner["priority"],
        )
        if winner["effect"] == "deny" and allows:
            reason += "; explicit deny overrides allow"
        return (
            {"effect": winner["effect"], "rule": winner["id"], "reason": reason},
            winner,
        )

    def _evaluate(self, subject, action, resource, tags):
        """Shared decision core; returns (decision, matched rules in order)."""
        tags = self._check_inputs(subject, action, resource, tags)

        matched = [
            r
            for r in self.rules
            if self._matches(r, subject, action, resource, tags)
        ]
        decision, _winner = self._select(matched)
        return decision, matched

    def decide(self, subject, action, resource, tags=None):
        result, _matched = self._evaluate(subject, action, resource, tags)
        return result

    @staticmethod
    def _validate_batch_item(item, index):
        # Within one item, error classes are checked unknown-field first,
        # then missing-field, then field-type; ties resolve in the fixed
        # subject/action/resource/tags order.
        unknown = [k for k in item if k not in _REQUEST_FIELDS]
        if unknown:
            raise PolicyBatchError("unknown_field", index, field=unknown[0])

        for field in _STRING_FIELDS:
            if field not in item:
                raise PolicyBatchError("missing_field", index, field=field)

        for field in _STRING_FIELDS:
            if not isinstance(item[field], str):
                raise PolicyBatchError("invalid_field_type", index, field=field)

        if "tags" in item:
            tags = item["tags"]
            if tags is not None and not isinstance(tags, Mapping):
                raise PolicyBatchError(
                    "invalid_field_type", index, field="tags"
                )

    @staticmethod
    def _validate_requests(requests):
        # Shared by decide_many(), compare() and coverage(): the whole
        # batch is checked before any decision is computed, so a malformed
        # batch never produces partial results.
        if not isinstance(requests, (list, tuple)):
            raise PolicyBatchError("invalid_batch", None)

        for index, item in enumerate(requests):
            if not isinstance(item, Mapping):
                raise PolicyBatchError("item_not_mapping", index)
            PolicyGate._validate_batch_item(item, index)

    @staticmethod
    def _validate_case_item(item, index):
        # Error classes are checked in the fixed precedence unknown-field,
        # missing-field, field-type, invalid-expectation value; nested
        # expectation fields take part in the same phases under dotted
        # names. A non-mapping expected cannot be inspected field by field,
        # so it skips the nested checks and surfaces in the type phase.
        unknown = [k for k in item if k not in _CASE_FIELDS]
        if unknown:
            raise PolicyVerificationError(
                "unknown_field", index, field=unknown[0]
            )

        expected = item.get("expected")
        expected_mapping = isinstance(expected, Mapping)
        if expected_mapping:
            nested_unknown = [
                k for k in expected if k not in _EXPECTATION_FIELDS
            ]
            if nested_unknown:
                raise PolicyVerificationError(
                    "unknown_field",
                    index,
                    field="expected." + nested_unknown[0],
                )

        for field in _REQUIRED_CASE_FIELDS:
            if field not in item:
                raise PolicyVerificationError(
                    "missing_field", index, field=field
                )

        if expected_mapping:
            for field in ("effect", "rule"):
                if field not in expected:
                    raise PolicyVerificationError(
                        "missing_field",
                        index,
                        field="expected." + field,
                    )

        for field in _STRING_FIELDS:
            if not isinstance(item[field], str):
                raise PolicyVerificationError(
                    "invalid_field_type", index, field=field
                )

        tags = item.get("tags")
        if tags is not None and not isinstance(tags, Mapping):
            raise PolicyVerificationError(
                "invalid_field_type", index, field="tags"
            )

        if not expected_mapping:
            raise PolicyVerificationError(
                "invalid_field_type", index, field="expected"
            )

        if expected["effect"] not in ("allow", "deny"):
            raise PolicyVerificationError(
                "invalid_expectation", index, field="expected.effect"
            )

        rule = expected["rule"]
        if rule is not None and not isinstance(rule, str):
            raise PolicyVerificationError(
                "invalid_expectation", index, field="expected.rule"
            )

    @staticmethod
    def _validate_cases(cases):
        # Whole-batch-first validation for verify(): every case is checked
        # before any decision is computed, so a malformed batch never
        # produces partial results.
        if not isinstance(cases, (list, tuple)):
            raise PolicyVerificationError("invalid_cases", None)

